// Generates src/matcher/psl-data.generated.ts (and the same data for the Swift VaultKit,
// app/mobile/modules/vault-kit/ios/Sources/VaultKit/Matcher/PSLData.generated.swift)
// from app/shared/public_suffix_list.dat.
// Run: pnpm --filter @localvault/core build:psl   (the generated file is committed)
// Output: all rules (ICANN + PRIVATE sections) as one space-separated string of ASCII/Punycode
// rules, e.g. "com co.uk *.ck !www.ck ...".
import { createHash } from 'node:crypto';
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { domainToASCII, fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const datPath = resolve(here, '../../../shared/public_suffix_list.dat');
const outPath = resolve(here, '../src/matcher/psl-data.generated.ts');
const swiftPath = resolve(
  here,
  '../../../mobile/modules/vault-kit/ios/Sources/VaultKit/Matcher/PSLData.generated.swift',
);

const dat = readFileSync(datPath);
const rules = new Set();
for (const line of dat.toString('utf8').split(/\r?\n/)) {
  const token = line.trim().split(/\s+/)[0] ?? '';
  if (token === '' || token.startsWith('//')) continue;
  let prefix = '';
  let body = token;
  if (body.startsWith('!')) {
    prefix = '!';
    body = body.slice(1);
  } else if (body.startsWith('*.')) {
    prefix = '*.';
    body = body.slice(2);
  }
  const ascii = domainToASCII(body.toLowerCase());
  if (ascii === '') throw new Error(`cannot convert rule: ${token}`);
  rules.add(prefix + ascii);
}

const compact = [...rules].sort().join(' ');
const sha = createHash('sha256').update(dat).digest('hex');
const out = `// @generated by scripts/build-psl.mjs from app/shared/public_suffix_list.dat. Do not edit.
// Public Suffix List, MPL 2.0 (https://publicsuffix.org/). ${rules.size} rules.
export const PSL_SOURCE_SHA256 = '${sha}';
export const PSL_COMPACT =
  '${compact}';
`;
writeFileSync(outPath, out);
console.log(`wrote ${outPath}: ${rules.size} rules, ${out.length} bytes`);

// Swift: the same compact string (rules are ASCII, so no escaping is needed beyond the quotes).
const swift = `// @generated by app/packages/core/scripts/build-psl.mjs from app/shared/public_suffix_list.dat. Do not edit.
// Public Suffix List, MPL 2.0 (https://publicsuffix.org/). ${rules.size} rules.
enum PSLData {
  static let sourceSha256 = "${sha}"
  static let compact = "${compact}"
}
`;
writeFileSync(swiftPath, swift);
console.log(`wrote ${swiftPath}: ${swift.length} bytes`);
